SELECT percent_rank() OVER (ORDER BY avg_value) AS percentile_rank FROM (SELECT AVG(value) AS avg_value FROM chartevents JOIN icustays ON chartevents.subject_id = icustays.subject_id WHERE itemid = 85806002 AND valueuom = 'mm[Hg]' AND (age(CURRENT_DATE, icustays.intime) BETWEEN 38 AND 48) AND (icustays.first_careunit = 'ICU' OR icustays.first_careunit = 'CCU') AND (icustays.subject_id = 43 AND gender = 'Female') AND (charttime BETWEEN intime AND (intime + interval '24 hours'))) AS avg_bp;